# Backfill mapping for the "CITCI Default" component names that existed
# before categories/locking were added — anything not listed here (a custom
# instructor-renamed component) is left as the OTHER default, unlocked.
_NAME_TO_CATEGORY = {
    "Attendance": "ATTENDANCE",
    "Quizzes": "QUIZ",
    "Recitation": "RECITATION",
    "Project": "PROJECT",
    "Examination": "EXAM",
}


def backfill_categories_and_lock_exam(apps, schema_editor):
    """CITCI policy: the Examination weight is fixed by the school; every
    other component is up to the instructor. Backfilling both the templates
    and every class's already-snapshotted scheme components applies that
    policy retroactively — it was already true practice, just not modeled."""
    GradingComponent = apps.get_model("grading", "GradingComponent")
    SchemeComponent = apps.get_model("grading", "SchemeComponent")

    for model in (GradingComponent, SchemeComponent):
        for name, category in _NAME_TO_CATEGORY.items():
            model.objects.filter(name=name).update(category=category)
        model.objects.filter(category="EXAM").update(is_locked=True)


